-- ============================================================
CREATE AUDIT POLICY sc_order_audit
    ACTIONS UPDATE ON orders,
            DELETE ON orders,
            INSERT ON agent_actions
    WHEN 'SYS_CONTEXT(''USERENV'', ''SESSION_USER'') != ''ADMIN'''
    EVALUATE PER SESSION;

