-- BEGIN INCLUDED FILE: loader-sql/32_deterministic_generated_artifacts.sql
-- ============================================================================
/*
 * 32_deterministic_generated_artifacts.sql
 * Deterministic post-load artifacts derived from fixed seed rows.
 */
SET DEFINE OFF
SET SERVEROUTPUT ON

DELETE FROM semantic_matches;
DELETE FROM signal_embeddings;
DELETE FROM product_embeddings;
COMMIT;

PROMPT Rebuilding deterministic point geometries
UPDATE fulfillment_centers
SET location = SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(longitude, latitude, NULL), NULL, NULL)
WHERE location IS NULL AND latitude IS NOT NULL AND longitude IS NOT NULL;

UPDATE customers
SET location = SDO_GEOMETRY(2001, 4326, SDO_POINT_TYPE(longitude, latitude, NULL), NULL, NULL)
WHERE location IS NULL AND latitude IS NOT NULL AND longitude IS NOT NULL;

COMMIT;

PROMPT Rebuilding deterministic product embeddings
SELECT ROW_NUMBER() OVER (ORDER BY p.product_id) AS embedding_id,
       p.product_id,
       p.product_name || ' ' || p.category || ' ' || NVL(p.description, '') || ' ' || b.brand_name AS embedding_text,
       VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING
         p.product_name || ' ' || p.category || ' ' || NVL(p.description, '') || ' ' || b.brand_name AS DATA) AS embedding
FROM products p
JOIN brands b ON p.brand_id = b.brand_id
ORDER BY p.product_id;

PROMPT Rebuilding deterministic signal embeddings
SELECT ROW_NUMBER() OVER (ORDER BY sp.post_id) AS embedding_id,
       sp.post_id,
       SUBSTR(sp.post_text, 1, 500) AS embedding_text,
       VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING SUBSTR(sp.post_text, 1, 500) AS DATA) AS embedding
FROM social_posts sp
ORDER BY sp.post_id;

PROMPT Rebuilding deterministic semantic matches
SELECT ROW_NUMBER() OVER (ORDER BY post_id, match_rank, product_id) AS match_id,
       post_id,
       product_id,
       similarity_score,
       match_rank,
       'vector' AS match_method
FROM (
  SELECT se.post_id,
         pe.product_id,
         ROUND(1 - VECTOR_DISTANCE(se.embedding, pe.embedding, COSINE), 5) AS similarity_score,
         ROW_NUMBER() OVER (
           PARTITION BY se.post_id
           ORDER BY VECTOR_DISTANCE(se.embedding, pe.embedding, COSINE), pe.product_id
         ) AS match_rank
  FROM signal_embeddings se
  CROSS JOIN product_embeddings pe
  JOIN social_posts sp ON sp.post_id = se.post_id
  WHERE sp.momentum_flag IN ('viral', 'mega_viral')
)
WHERE match_rank <= 3
ORDER BY post_id, match_rank, product_id;

COMMIT;
-- ============================================================================
-- END INCLUDED FILE: loader-sql/32_deterministic_generated_artifacts.sql
