SELECT 'finance workshop deterministic load complete' AS status,
       (SELECT COUNT(*) FROM user_views
        WHERE view_name IN (
          'FINANCE_INSTITUTIONS_V','FINANCE_PRODUCTS_V','RISK_SIGNALS_V',
          'SIGNAL_SOURCES_V','CLIENT_TRANSACTIONS_V','SERVICE_CENTERS_V',
          'SERVICE_CAPACITY_V','SERVICE_ROUTES_V'
        )) AS finance_semantic_views,
       (SELECT COUNT(*) FROM finance_products_v) AS products,
       (SELECT COUNT(*) FROM risk_signals_v) AS risk_signals,
       (SELECT COUNT(*) FROM client_transactions_v) AS transactions,
       (SELECT COUNT(*) FROM service_centers_v) AS service_centers,
       (SELECT COUNT(*) FROM service_capacity_v) AS service_capacity_rows,
       (SELECT COUNT(*) FROM service_routes_v) AS service_route_rows,
       (SELECT COUNT(*) FROM fraud_entities) AS fraud_entities,
       (SELECT COUNT(*) FROM signal_embeddings) AS signal_embeddings,
       (SELECT COUNT(*) FROM semantic_matches) AS semantic_matches,
       (SELECT COUNT(*) FROM user_objects WHERE status <> 'VALID') AS invalid_objects
FROM dual;

DECLARE
  l_count PLS_INTEGER;

  PROCEDURE require_exact_rows(
    p_table_name IN VARCHAR2,
    p_expected    IN PLS_INTEGER
  ) IS
  BEGIN
    EXECUTE IMMEDIATE
      'SELECT COUNT(*) FROM ' || DBMS_ASSERT.SIMPLE_SQL_NAME(p_table_name)
      INTO l_count;
    IF l_count <> p_expected THEN
      RAISE_APPLICATION_ERROR(
        -20211,
        p_table_name || ' expected ' || p_expected || ' rows but found ' || l_count || '.'
      );
    END IF;
  END;
BEGIN
  require_exact_rows('APP_USERS', 7);
  require_exact_rows('PRODUCTS', 79);
  require_exact_rows('ORDERS', 3000);
  require_exact_rows('ORDER_ITEMS', 8913);
  require_exact_rows('SOCIAL_POSTS', 5000);
  require_exact_rows('FRAUD_ENTITIES', 25);
  require_exact_rows('PRODUCT_EMBEDDINGS', 79);
  require_exact_rows('SIGNAL_EMBEDDINGS', 5000);
  require_exact_rows('SEMANTIC_MATCHES', 1599);
  DBMS_OUTPUT.PUT_LINE('FINANCE_HANDOFF_DATA_ACCEPTANCE_OK');
END;
/

BEGIN
  sc_security_ctx.clear_user_context;
END;
/

PROMPT FINANCE_HANDOFF_LOADER_COMPLETE
EXIT SUCCESS
